#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""从任务单一JSON数据源生成离线互动首页。开发时先修改data/tasks.json。"""
from pathlib import Path
import json, html

AUTHOR_LINK = '<a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">Andy个人官网 ↗</a>'
AUTHOR_CONTACT = '求职、职业发展及 AI 应用等相关咨询，可自愿联系微信 <strong>AIPMAndy</strong> · <a href="https://metaver.vip/" target="_blank" rel="noopener noreferrer">Andy个人官网 ↗</a>。免费攻略可独立使用，咨询不承诺录用或涨薪结果。'

CSS='\n:root{color-scheme:light;--bg:#f6f7fa;--paper:#fff;--ink:#17212d;--muted:#637184;--line:#e3e7ed;--blue:#2764e7;--blue2:#e9efff}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","PingFang SC","Microsoft Yahei",sans-serif;color:var(--ink);line-height:1.65}main{max-width:1130px;margin:auto;padding:28px 24px 90px}\n.hero{padding:48px 50px;background:linear-gradient(125deg,#101928,#293650);border-radius:28px;color:white;box-shadow:0 14px 48px #17213a25}.eyebrow{color:#a9bfea;font-weight:700;letter-spacing:.09em;font-size:12px}.hero h1{font-size:clamp(31px,5vw,56px);line-height:1.2;letter-spacing:-.05em;margin:13px 0 16px}.hero p{max-width:720px;font-size:16px;color:#e2e7f2}.hero .muted{font-size:13px;color:#b4c2da}.links{display:flex;flex-wrap:wrap;gap:10px;margin-top:21px}.links a,.links button{display:inline-block;border:1px solid #ffffff59;border-radius:12px;padding:9px 14px;color:white;background:#ffffff10;font-size:13px;text-decoration:none;cursor:pointer}.links a:hover,.links button:hover{background:#ffffff30}\n.bar{display:flex;flex-wrap:wrap;gap:11px;justify-content:space-between;align-items:center;margin:22px 0}.kpi{font-size:14px;color:var(--muted);font-weight:600}.bar button,.bar select,.bar input{font:inherit;padding:11px 13px;border:1px solid var(--line);background:white;border-radius:12px}.bar input{flex:1;min-width:180px}.bar select{min-width:140px}.bar button{cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.card{background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:22px;box-shadow:0 3px 16px #1a24410a}.card h2{font-size:18px;line-height:1.35;margin:0 0 8px;letter-spacing:-.02em}.card p{margin:10px 0}.eyebrow2{font-size:12px;font-weight:700;color:#466dd0;margin:0 0 8px}.meta{font-size:12px;color:var(--muted)}.line{height:1px;background:var(--line);margin:14px 0}.small-label{font-size:12px;color:#567;letter-spacing:.04em;font-weight:700;margin:12px 0 3px}.value{font-size:14px}.task-row{display:flex;gap:12px;align-items:start}.task-row input{width:18px;height:18px;margin:4px 0;accent-color:var(--blue)}.task-body{min-width:0;flex:1}.task-card.done{opacity:.65}.tag{color:#1f5bc4;background:var(--blue2);display:inline-block;font-size:11px;padding:3px 8px;border-radius:20px}.tool{margin:25px 0;background:#fefeff}.tool-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.tool-grid label{display:block;font-size:13px;color:var(--muted)}.tool-grid input,.tool-grid select{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;font:inherit;color:var(--ink)}.tool .output{padding:15px;border-radius:14px;background:#eff4ff;color:#123c86;font-weight:600;margin-top:13px;white-space:pre-line}.tool .note{font-size:12px;color:var(--muted)}.chap-nav{display:flex;gap:7px;flex-wrap:wrap;padding:14px 0}.chap-nav button{padding:8px 11px;border-radius:100px;background:white;border:1px solid var(--line);font-size:13px;cursor:pointer}.chap-nav button.active{background:#1b4fa8;color:#fff}.section-header{margin-top:28px}.section-header h2{margin:0;font-size:22px}.section-header p{color:var(--muted);font-size:14px;margin:3px 0 15px}footer{color:var(--muted);font-size:12px;padding-top:30px}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #80a9ff;outline-offset:2px}#no-result{display:none;padding:28px;background:white;border-radius:18px;text-align:center;color:var(--muted)}@media(max-width:700px){main{padding:14px 13px 50px}.hero{padding:29px 22px;border-radius:19px}.grid,.tool-grid{grid-template-columns:1fr}.card{padding:17px}.bar{align-items:stretch}.bar>*{width:100%}}\n'
JS='\n(()=>{\n const data=__DATA_JSON__;\n const key=\'andy-career-progress-\'+data.slug;\n let checked={};try{checked=JSON.parse(localStorage.getItem(key)||\'{}\');if(!checked||typeof checked!==\'object\')checked={}}catch{checked={}}\n const checks=[...document.querySelectorAll(\'.task-check\')],search=document.querySelector(\'#search\'),filter=document.querySelector(\'#phase-filter\'),cards=[...document.querySelectorAll(\'.task-card\')];\n function update(){let n=0;for(const c of checks){c.checked=!!checked[c.dataset.id];c.closest(\'.task-card\').classList.toggle(\'done\',c.checked);if(c.checked)n++}document.querySelector(\'#progress\').textContent=`已完成 ${n} / ${checks.length} 项`};\n function save(){try{localStorage.setItem(key,JSON.stringify(checked))}catch(e){alert(\'浏览器无法保存进度，请使用导出功能。\')}};\n checks.forEach(c=>c.addEventListener(\'change\',()=>{checked[c.dataset.id]=c.checked;save();update()}));\n function applyFilter(){let visible=0;for(const c of cards){let match=(filter.value===\'all\'||c.dataset.phase===filter.value)&&c.textContent.toLowerCase().includes(search.value.trim().toLowerCase());c.hidden=!match;if(match)visible++}document.querySelector(\'#no-result\').style.display=visible?\'none\':\'block\';document.querySelector(\'#shown\').textContent=`当前显示 ${visible} 项`;document.querySelectorAll(\'.chap-nav button\').forEach(b=>b.classList.toggle(\'active\',b.dataset.phase===filter.value));}\n search.addEventListener(\'input\',applyFilter);filter.addEventListener(\'change\',applyFilter);document.querySelectorAll(\'.chap-nav button\').forEach(b=>b.addEventListener(\'click\',()=>{filter.value=b.dataset.phase;applyFilter();document.querySelector(\'#tasks\').scrollIntoView({behavior:\'smooth\'})}));\n document.querySelector(\'#export\').addEventListener(\'click\',()=>{let payload={project:data.slug,exported_at:new Date().toISOString(),checked};let blob=new Blob([JSON.stringify(payload,null,2)],{type:\'application/json\'});let url=URL.createObjectURL(blob);let a=document.createElement(\'a\');a.href=url;a.download=data.slug+\'-progress.json\';a.click();URL.revokeObjectURL(url)});\n document.querySelector(\'#import\').addEventListener(\'click\',()=>document.querySelector(\'#upload\').click());document.querySelector(\'#upload\').addEventListener(\'change\',async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>1e6)throw Error(\'文件过大\');let input=JSON.parse(await file.text());if(input.project!==data.slug||typeof input.checked!==\'object\'||!input.checked)throw Error(\'项目不匹配\');const known=new Set(checks.map(c=>c.dataset.id));checked={};for(const [k,v] of Object.entries(input.checked)){if(known.has(k)&&typeof v===\'boolean\')checked[k]=v}save();update();alert(\'进度已导入\')}catch(err){alert(\'导入失败：\'+err.message)}e.target.value=\'\'});\n document.querySelector(\'#print\').addEventListener(\'click\',()=>window.print());\n const calc=document.querySelector(\'#calc\');\n if(data.kind===\'executive\'){\n  let labels=[\'业务结果\',\'影响力\',\'人员培养\',\'预算意识\',\'业务决策\',\'管理层表达\'];\n  calc.innerHTML=\'<h2>能力证据自评 · 非晋升概率预测</h2><p class="note">每项0=没有证据，1=参与，2=独立完成，3=带队完成，4=跨周期重复验证。请用实际项目证据支撑分数。</p><div class="tool-grid">\'+labels.map((x,i)=>`<label>${x}<select class="score"><option value="0">0 无证据</option><option value="1">1 参与</option><option value="2">2 独立完成</option><option value="3">3 带队完成</option><option value="4">4 重复验证</option></select></label>`).join(\'\')+\'</div><p class="output" id="calc-result" role="status"></p>\';\n  function show(){let a=[...calc.querySelectorAll(\'select\')].map(s=>+s.value);let low=a.map((v,i)=>({v,label:labels[i]})).sort((a,b)=>a.v-b.v).slice(0,2);calc.querySelector(\'#calc-result\').textContent=`证据累计 ${a.reduce((x,y)=>x+y,0)} / 24；当前证据最少：${low.map(x=>x.label).join(\'、\')}。这是自评与练习排序，不代表晋升资格，也不能跨公司比较。`}\n  calc.querySelectorAll(\'select\').forEach(s=>s.addEventListener(\'change\',show));show();\n }else{\n  calc.innerHTML=\'<h2>Offer税前年现金拆分 · 本地计算</h2><p class="note">固定月薪和发薪月数只有在确属保证支付时才计入保底。可变奖金与股票单独列示。默认金额为0，请填写书面确认的真实数据；所有输入仅在本机计算，不上传。</p><div class="tool-grid"><label>固定税前月薪（元）<input id="month" type="number" value="0" min="0" step="1000"></label><label>保证发薪月数<input id="months" type="number" value="12" min="0" max="24" step="1"></label><label>保证年度奖金（元）<input id="guaranteed" type="number" value="0" min="0" step="1000"></label><label>稳定年度现金补贴（元）<input id="allowance" type="number" value="0" min="0" step="1000"></label><label>浮动年度奖金预估（元）<input id="variable" type="number" value="0" min="0" step="1000"></label><label>一次性签字费（元）<input id="signon" type="number" value="0" min="0" step="1000"></label></div><p class="output" id="calc-result" role="status"></p><p class="note">签字费如果有返还条件或尚未确定，需要单独确认；税后收入、期权流动性、社保和不同年度归属不在此算术示范范围内。</p>\';\n  function show(){let get=id=>{let n=Number(calc.querySelector(\'#\'+id).value);return Number.isFinite(n)&&n>=0?n:0};let fixed=get(\'month\')*get(\'months\')+get(\'guaranteed\')+get(\'allowance\'),fmt=n=>Math.round(n).toLocaleString(\'zh-CN\');calc.querySelector(\'#calc-result\').textContent=`持续年度保底税前现金：¥${fmt(fixed)}\\n首年如签字费符合兑现条件：¥${fmt(fixed+get(\'signon\'))}\\n另有非保证浮动奖金预估：¥${fmt(get(\'variable\'))}（不计入保底）`}\n  calc.querySelectorAll(\'input\').forEach(i=>i.addEventListener(\'input\',show));show();\n }\n update();applyFilter();\n})();\n'

def main():
    here=Path(__file__).resolve().parent
    data=json.loads((here/'data/tasks.json').read_text(encoding='utf-8'))
    kind='executive' if 'executive' in data['slug'] else 'salary'
    chapters=[]
    for ch in data['chapters']:
        group=[x for x in data['tasks'] if x['phase']==ch['code']]
        chapters.append((ch['code'],ch['title'],ch['description'],group))
    opts=''.join(f'<option value="{html.escape(code)}">{i:02} · {html.escape(title)}</option>' for i,(code,title,desc,items) in enumerate(chapters))
    nav=''.join(f'<button type="button" data-phase="{html.escape(code)}">{i:02} {html.escape(title)}</button>' for i,(code,title,desc,items) in enumerate(chapters))
    groups=[]
    for i,(code,title,desc,items) in enumerate(chapters):
        for k,t in enumerate(items,1):
            groups.append(f"""<article class=\"card task-card\" data-phase=\"{html.escape(code)}\" data-id=\"{t['id']}\"><div class=\"eyebrow2\">第{i:02}章 · {html.escape(title)} · {k}/{len(items)}</div><div class=\"task-row\"><input type=\"checkbox\" class=\"task-check\" data-id=\"{t['id']}\" aria-label=\"完成：{html.escape(t['title'],quote=True)}\"><div class=\"task-body\"><h2>{html.escape(t['title'])}</h2><div class=\"small-label\">具体怎么做</div><p class=\"value\">{html.escape(t['action'])}</p><div class=\"small-label\">完成凭证</div><p class=\"value\">{html.escape(t['proof'])}</p><div class=\"small-label\">卡住怎么办</div><p class=\"value\">{html.escape(t['blocked'])}</p><p><a href="guides/{code}.html" target="_blank" rel="noopener noreferrer">阅读本章完整攻略 ↗</a></p></div></div></article>""")
    title=data['name'];slug=data['slug'];safe=lambda x:html.escape(x,quote=True)
    note='六维能力证据自评' if kind=='executive' else '税前年现金拆分计算器'
    page=f"""<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"免费开源职业指南，50项可执行任务和{note}\"><title>{safe(title)}｜AI酋长Andy</title><style>{CSS}</style></head><body><main><header class=\"hero\"><div class=\"eyebrow\">AI 酋长 Andy · 免费开源职业指南 · 2026</div><h1>{safe(title)}</h1><p>10章 · 50项任务 · 10套SOP · 26份模板 · 可复制话术</p><p>每一项都有具体行动、完成凭证、受阻处理。</p><nav class=\"links\" aria-label=\"主要导航\"><a href=\"read.html\">阅读10章全文</a><a href=\"evidence/index.html\">查看原始研究与官方数据</a><a href=\"https://github.com/AIPMAndy/{slug}\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub项目</a><a href=\"https://metaver.vip/\" target=\"_blank\" rel=\"noopener noreferrer\">作者官网</a><a href=\"https://github.com/AIPMAndy/how-to-survive-unemployment\" target=\"_blank\" rel=\"noopener noreferrer\">失业自救指南</a></nav><p class=\"muted\">所有功能可离线运行，无账号、无第三方脚本、无上传；任务进度只在本机保存，可导出。</p></header><section class=\"card\" style=\"margin-top:20px\"><div class=\"eyebrow2\">SOURCE-BACKED · 可独立核查</div><h2>数据和原始研究就在正文中</h2><p>每章附真实来源、研究样本、结论、适用范围和对应行动。官网招聘 JD 与实验数据不用于承诺个人就业结果。</p><p><a href=\"evidence/index.html\">打开证据资料库 →</a>　·　<a href=\"read.html\">逐章查看原始引用 →</a></p></section><section class=\"tool card\" id=\"calc\" aria-label=\"辅助决策工具\"></section><nav class=\"chap-nav\" aria-label=\"章节筛选\"><button type=\"button\" data-phase=\"all\" class=\"active\">全部章节</button>{nav}</nav><section class=\"bar\" id=\"tasks\"><strong id=\"progress\" class=\"kpi\" aria-live=\"polite\">已完成 0 / 50 项</strong><span id=\"shown\" class=\"kpi\">当前显示50项</span><input id=\"search\" type=\"search\" placeholder=\"搜索任务、行动或困难\" aria-label=\"搜索任务\"><select id=\"phase-filter\" aria-label=\"筛选章节\"><option value=\"all\">全部章节</option>{opts}</select><button id=\"export\" type=\"button\">导出进度</button><button id=\"import\" type=\"button\">导入进度</button><input id=\"upload\" type=\"file\" accept=\"application/json,.json\" hidden><button id=\"print\" type=\"button\">打印</button></section><div id=\"no-result\" role=\"status\">没有符合条件的任务，换个关键词试试。</div><section class=\"grid\" aria-label=\"行动卡\">{''.join(groups)}</section><footer>{AUTHOR_CONTACT}勿在公开Issue发布个人工资、合同或公司机密。<p>最后整理：{data['last_reviewed']}。薪酬和职位的法律、商业与个案限制须自行核对。</p></footer></main><script>{JS.replace('__DATA_JSON__',json.dumps({'slug':slug,'kind':kind},ensure_ascii=False))}</script></body></html>"""
    (here/'index.html').write_text(page,encoding='utf-8')
    # 同步重新生成Markdown章节，避免互动页和手册出现两个版本。
    (here/'guides').mkdir(exist_ok=True)
    for ci,ch in enumerate(data['chapters']):
        group=[x for x in data['tasks'] if x['phase']==ch['code']]
        rows=[f"# 第{ci:02d}章 · {ch['title']}", '',ch['description'],'',
              '> 读法：每步有具体操作、完成凭证、卡住怎么办。敏感资料只留在本人私有目录。', '']
        for ti,t in enumerate(group,1):
            rows += [f"## {ti}. {t['title']}", '',f"**具体操作：** {t['action']}", '',
                     f"**完成凭证：** {t['proof']}", '',f"**卡住怎么办：** {t['blocked']}", '',
                     '- [ ] 完成并留存合规凭证', '']
        # 追加编辑版深入章节（单独维护；重新构建不会丢失）
        deepfile=here/'deepdives'/f"{ch['code']}.md"
        if deepfile.exists():
            rows += ['',deepfile.read_text(encoding='utf-8').strip(),'']
        rows += ['---','','[返回总览](../README.md) · [离线互动任务页](../index.html)','']
        (here/'guides'/f"{ch['code']}.md").write_text('\n'.join(rows),encoding='utf-8')

    # 在开发环境有mistune时生成适合手机阅读的纯静态HTML章节。生成文件可直接提交，读者无须安装任何依赖。
    try:
        import mistune
        markdown=mistune.create_markdown(escape=True,plugins=['table','strikethrough','task_lists','url'])
    except ImportError:
        markdown=None
    reading_css="""
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f5f6f9;color:#1d2939;font:16px/1.85 -apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft Yahei',sans-serif}a{color:#275bc4}nav{background:#131e30;color:white;padding:16px max(18px,calc((100vw - 840px)/2));display:flex;gap:18px;flex-wrap:wrap}nav a{color:#fff;text-decoration:none}article{margin:28px auto;padding:30px 40px;max-width:860px;background:white;border:1px solid #e7e9ed;border-radius:18px}h1{font-size:30px;line-height:1.35}h2{font-size:23px;margin-top:34px;border-bottom:1px solid #e7e9ed;padding-bottom:7px}h3{font-size:18px}table{display:block;overflow-x:auto;border-collapse:collapse;white-space:normal;margin:15px 0}th,td{border:1px solid #dfe4ea;padding:9px 12px;text-align:left;min-width:90px}th{background:#f3f5f9}blockquote{border-left:4px solid #427be1;background:#f3f7ff;padding:3px 15px;margin:18px 0}code{word-break:break-word;background:#f1f3f7;border-radius:4px;padding:2px 5px}pre{overflow:auto;padding:15px;background:#161e2b;color:#fff;border-radius:9px}pre code{background:none}li{margin:7px 0}p{overflow-wrap:anywhere}footer{max-width:860px;margin:20px auto 55px;padding:0 18px;font-size:13px;color:#627081}@media(max-width:650px){article{margin:10px 8px;padding:18px 17px;border-radius:12px;font-size:15px}h1{font-size:24px}h2{font-size:20px}}
"""
    if markdown:
        for ch in data['chapters']:
            code=ch['code']
            source=(here/'guides'/f'{code}.md').read_text(encoding='utf-8')
            rendered=markdown(source)
            htmlpage=f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(ch["title"],quote=True)}的完整免费职业实操指南"><title>{html.escape(ch["title"])} | {html.escape(title)}</title><style>{reading_css}</style></head><body><nav><a href="../index.html">互动任务</a><a href="../read.html">全部章节</a><a href="../evidence/index.html">证据资料库</a><a href="../README.md">GitHub README</a>{AUTHOR_LINK}</nav><article>{rendered}</article><footer>{AUTHOR_CONTACT}<p>免费开源指南｜2026-10-12核验关键来源｜个人经历与公司资料请保密｜不承诺晋升或录用</p></footer></body></html>'
            (here/'guides'/f'{code}.html').write_text(htmlpage,encoding='utf-8')
        cards=''.join(f'<a class="ch" href="guides/{ch["code"]}.html"><small>第{i:02}章</small><strong>{html.escape(ch["title"])}</strong><p>{html.escape(ch["description"])}</p></a>' for i,ch in enumerate(data['chapters']))
        read=f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}｜阅读全部章节</title><style>{reading_css}.chapters{{display:grid;grid-template-columns:1fr 1fr;gap:13px}}a.ch{{border:1px solid #e3e7ed;border-radius:12px;padding:18px;text-decoration:none;color:#1d2939}}a.ch:hover{{border-color:#427be1;background:#f7faff}}a.ch strong{{display:block;font-size:17px}}a.ch p{{color:#687589;font-size:13px;margin:5px 0}}a.ch small{{color:#427be1}}@media(max-width:650px){{.chapters{{grid-template-columns:1fr}}}}</style></head><body><nav><a href="index.html">互动首页</a><a href="evidence/index.html">证据资料库</a><a href="https://github.com/AIPMAndy/{slug}" rel="noopener noreferrer">仓库主页</a>{AUTHOR_LINK}</nav><article><h1>{html.escape(title)}</h1><p>选你最需要的一章。全部内容静态HTML，离线可读，无须登录或第三方插件。</p><div class="chapters">{cards}</div></article><footer>{AUTHOR_CONTACT}</footer></body></html>'
        (here/'read.html').write_text(read,encoding='utf-8')
    else:
        print('mistune not installed: keeping existing chapter HTML, install optional "mistune>=3,<4" to regenerate them')

    # Build an offline-responsive evidence library from checked, machine-readable source_registry.csv.
    import csv
    regfile=here/'evidence/source_registry.csv'
    if regfile.exists():
        with regfile.open(encoding='utf-8-sig',newline='') as fin:
            records=list(csv.DictReader(fin))
        ecards=[]
        for source in records:
            def v(k): return html.escape(source[k])
            ecards.append(f'<section class="card evidence"><span class="kind">{v("source_type")} · {v("evidence_id")}</span><h2>{v("title")}</h2><dl><dt>原始样本与范围</dt><dd>{v("sample_or_scope")}</dd><dt>研究或法规实际证明</dt><dd>{v("observed_result")}</dd><dt>不可以外推的地方</dt><dd class="warn">{v("limitation")}</dd><dt>读者该做什么</dt><dd>{v("reader_action")}</dd></dl><a class="link" href="{html.escape(source["original_url"],quote=True)}" rel="noopener noreferrer" target="_blank">核对原始研究 / 官方文件 ↗</a></section>')
        evcss="body{margin:0;background:#f6f7fb;color:#182338;font:15px/1.75 -apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif}main{max-width:1050px;margin:auto;padding:24px 18px 80px}.hero{border-radius:23px;background:#101b2d;color:#f6faff;padding:36px 40px}.hero h1{font-size:33px;margin:0 0 10px}.hero p{max-width:760px;color:#ccd8e9}a{color:#2963d4}.hero a{color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:24px}.card{background:white;border-radius:17px;padding:24px;border:1px solid #e2e7f0}.card h2{font-size:19px;margin:7px 0 15px}.kind{font-size:12px;color:#3165ae;font-weight:700}dt{font-weight:700;color:#354966;margin-top:11px;font-size:13px}dd{margin:3px 0 9px;font-size:14px}.warn{color:#9b513e}.link{display:inline-block;padding-top:9px;font-weight:700}footer{color:#6a788b;font-size:12px;margin-top:24px}@media(max-width:670px){.grid{grid-template-columns:1fr}.hero{padding:25px 22px}.hero h1{font-size:26px}.card{padding:19px}}"
        evpage='<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>真实研究证据库 · '+html.escape(title)+'</title><style>'+evcss+'</style></head><body><main><header class="hero"><nav aria-label="主要导航"><a href="../index.html">← 返回互动首页</a> · <a href="../read.html">阅读完整章节</a> · '+AUTHOR_LINK+'</nav><h1>真实研究与原始证据库</h1><p>'+str(len(records))+'条资料，逐条注明原始样本、实际结论、适用边界和可执行行动。原始来源由出版机构提供；不保证求职与晋升结果。更新日期：2026-10-12。</p></header><div class="grid">'+''.join(ecards)+'</div><footer>'+AUTHOR_CONTACT+'<p>本站仅对外链接官方/原始出处；数据与职位可能更新，不采集用户输入。</p></footer></main></body></html>'
        (here/'evidence/index.html').write_text(evpage,encoding='utf-8')
